    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Genitive, Number::Singular,) => Some(2),
            (Case::Genitive, Number::Plural,) => Some(3),
            (Case::Partitive, Number::Singular,) => Some(4),
            (Case::Partitive, Number::Plural,) => Some(5),
            (Case::Dative, Number::Singular,) => Some(6),
            (Case::Dative, Number::Plural,) => Some(7),
            (Case::Instrumental, Number::Singular,) => Some(8),
            (Case::Instrumental, Number::Plural,) => Some(9),
            (Case::Illative, Number::Singular,) => Some(10),
            (Case::Illative, Number::Plural,) => Some(11),
            (Case::Inessive, Number::Singular,) => Some(12),
            (Case::Inessive, Number::Plural,) => Some(13),
            (Case::Elative, Number::Singular,) => Some(14),
            (Case::Elative, Number::Plural,) => Some(15),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

